<?php
/**
 * POST /api/v2/attachments/upload
 *
 * Body: { "login-id": "...", "token": "...", "service": "notefox",
 *         "id": "<id generated by the client>",
 *         "data": "data:image/webp;base64,..." }
 *
 * Uploading again the same id replaces the image (an interrupted upload can
 * simply be retried). See include/attachments.php.
 */

include_once(__DIR__ . "/../../include/bootstrap.php");

req_require_post();

$c = db();

list($session, $service) = v2_attachments_begin($c);
$dek = v2_require_dek($session);

$id = req_string("id", 64);
if (!v2_attachment_id_valid($id)) {
    api_error(ERR_MISSING_PARAMETERS);
}
$body = req_body();
if (!isset($body["data"]) || !is_string($body["data"])) {
    api_error(ERR_MISSING_PARAMETERS);
}
$image = v2_attachment_parse($body["data"]);
if ($image === null) {
    api_error(ERR_MISSING_PARAMETERS);
}

v2_rate_limit($c, "attachments-upload", $session["user-id"], 60, 60, 60);

try {
    $result = v2_attachment_store($c, $session["user-id"], $service, $id, $image, $dek);
} catch (Throwable $e) {
    error_log("[sav-account] attachments/upload: " . $e->getMessage());
    api_error(ERR_INTERNAL);
}

if ($result === "quota") {
    api_error(ERR_ATTACHMENTS_QUOTA, v2_attachments_usage($c, $session["user-id"], $service));
}

api_ok(array_merge(array("service" => $service, "id" => $id), v2_attachments_usage($c, $session["user-id"], $service)));
?>
